using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class RouteAroundPole {
 static float D(Vector3 p,Vector3 a,Vector3 b){var d=new Vector2(b.x-a.x,b.z-a.z);var q=new Vector2(p.x-a.x,p.z-a.z);return(q-d*Mathf.Clamp01(Vector2.Dot(q,d)/d.sqrMagnitude)).magnitude;}
 public static string Main(){var root=GameObject.Find("New_Map").transform;var t=root.GetComponentInChildren<Terrain>();var td=t.terrainData;var h=root.Find("11_Five_Hangar_Farm").Cast<Transform>().First(x=>x.name.StartsWith("Hangar 3"));var a=new Vector3(0,0,32);var b=new Vector3(-18,0,28);var c=h.TransformPoint(new Vector3(0,0,18));int n=td.alphamapWidth;var alpha=td.GetAlphamaps(0,0,n,n);for(int z=0;z<n;z++)for(int x=0;x<n;x++){var p=t.transform.position+new Vector3(x/(float)(n-1)*td.size.x,0,z/(float)(n-1)*td.size.z);float d=Mathf.Min(D(p,a,b),D(p,b,c));float w=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.8f,4.5f,d));if(w<=0)continue;for(int l=0;l<td.alphamapLayers;l++)alpha[z,x,l]*=1-w;alpha[z,x,1]+=w*.3f;alpha[z,x,2]+=w*.1f;alpha[z,x,6]+=w*.6f;}td.SetAlphamaps(0,0,alpha);EditorUtility.SetDirty(td);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);return "Hangar 3 approach curves around existing service pole.";}
}
